"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1010-08-15:0":{"b": ["Belensiye (Valencia) ket destê azadkiriyên Amirî Mubarek û Muzeffer", "38ac8e22"], "d": ["Bi hilweşîna desthilata neviyên Hacib Mensûr re Belensiye ket bin rêveberiya azadkiriyên Amiriyan Mubarek û Muzeffer; li Endelusê mîrektiyên taîfeyan dest pê kirin ku derkevin holê.", "82f013cc"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1013-01-01:0":{"b": ["Silêman el-Musteîn û alîgirên wî ketin Qurtubayê û Hîşamê II. dîsa ji text daxistin; li bajêr herî kêm şêst alim hatin kuştin (403/1013; çavkanî salê dide, roj tune ye).", "e863c0b4"], "d": ["Silêman el-Musteîn û alîgirên wî ketin Qurtubayê û Hîşamê II. dîsa ji text daxistin; li bajêr herî kêm şêst alim hatin kuştin (403/1013; çavkanî salê dide, roj tune ye).", "e863c0b4"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1016-01-01:0":{"b": ["Hemmûdiyan Qurtuba û textê Endelusê bi dest xistin", "a8a8ea65"], "d": ["Hemmûdiyên Şîe, ku îdîa dikirin ji nifşa Elewî ne, ji bêhêziya xanedana Emewî sûd wergirtin û di 1016an de dest danîn ser Qurtuba û textê xîlafetê; Qurtuba di navbera 1016-1022an de di bin serdestiya wan de ma.", "b088ab2a"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1021-01-01:0":{"b": ["Xanedana Amiriyan bi navenda Belensiyeyê hat avakirin (1021-1094)", "ebf0b6e2"], "d": ["Neviyê Hacib el-Mensûr Ebdulazîz b. Ebdurrehman di 1021an de mîrektiya taîfeyê ya Amirî ya ku navenda wê Belensiye bû ava kir; xanedan bi hin navberan heta 1094an ajot.", "dc1ccee5"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1023-03-26:0":{"b": ["Qadî Îbn Abbad Îşbîliye wek navenda hikûmetê îlan kir (Abbadî)", "931db55e"], "d": ["Qadî Ebulqasim Îbn Abbad di sala 414an de (1023) Îşbîliye wek navenda hikûmetê îlan kir; mîrektiya taîfeyê ya Abbadî bû yek ji navendên herî girîng ên Endelusê.", "51e3b6d5"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1031-01-01:0":{"b": ["Qurtuba di bin rêveberiya Cehweriyan de bû komar (1031-1070)", "943bc77c"], "d": ["Piştî dawîbûna xanedana Emewî, Qurtuba ji 1031an heta 1070an bû komarek di bin rêveberiya Cehweriyan de.", "6afd1a28"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1049-06-05:0":{"b": ["Gava wezîrê Fatimî el-Yazûrî serokê Zuxbeyê wek mîrê Trablusgerb û Qabisê tayîn kir, Benî Hîlal berê xwe da rojava (441, 1049).", "481a1144"], "d": ["Gava wezîrê Fatimî el-Yazûrî serokê Zuxbeyê wek mîrê Trablusgerb û Qabisê tayîn kir, Benî Hîlal berê xwe da rojava (441, 1049).", "481a1144"]},
